public struct Disadvantage: Decodable, Equatable, Sendable, Identifiable {
  public typealias ID = UUID

  public let id: ID

  /// Number of available levels.
  public let levels: Int?

  public let subtype: AdvantageDisadvantageSubtype?

  /// Rules for building the name of an activatable. These rules are used when the activatable doesn't have a custom name specified.
  public let nameBuilderRules: ActivatableNameBuilderRules?

  /// Definitions for possible options for the activatable entry, derived from entry categories.
  ///
  /// Note that this is only a full definition of options for simple logic that can be made explicit using the more detailed configuration for both derived categories and explicit options. There are quite a few entries whose option logic cannot be fully represented here, so that it needs to be implemented manually.
  public let selectOptions: SelectOptions?

  /// The number stating how often you can buy the entry. The **default** depends on the entry type:
  ///
  /// - **Advantage:** `1` in all cases (as specified in the **Core Rules**)
  /// - **Disadvantage:** `1` in all cases (as specified in the **Core Rules**)
  /// - **Special Abilities:** `1` if no options can be selected, otherwise the number of possible options
  ///
  /// The maximum is only set if it differs from the defaults specified above.
  public let maximum: Int?

  public let prerequisites: AdvantageDisadvantagePrerequisites?

  /// The adventure points value.
  public let apValue: AdventurePointsValue

  /// Does this advantage count towards the maximum of AP to be spent on advantages?
  public let hasMaximumSpentInfluence: Bool

  /// Does this advantage exclusively applies to arcane spellworks and not to magical actions and magical applications?
  public let isExclusiveToArcaneSpellworks: Bool

  /// References to where in which publications this entry has been defined. Entries may also be added or removed in later printings.
  public let src: PublicationRefs

  /// All translations for the entry, identified by IETF language tag (BCP47).
  public let translations: LocaleMap<DisadvantageTranslation>

  private enum CodingKeys: String, CodingKey {
    case levels = "levels"
    case subtype = "subtype"
    case nameBuilderRules = "nameBuilderRules"
    case selectOptions = "select_options"
    case maximum = "maximum"
    case prerequisites = "prerequisites"
    case apValue = "ap_value"
    case hasMaximumSpentInfluence = "has_maximum_spent_influence"
    case isExclusiveToArcaneSpellworks = "is_exclusive_to_arcane_spellworks"
    case src = "src"
    case translations = "translations"
  }

  public init(from decoder: Decoder) throws {
    let container = try decoder.container(keyedBy: CodingKeys.self)

    let databaseInstanceIdKey = CodingUserInfoKey.databaseInstanceIdKey
    let explicitId = if let databaseInstanceIdKey {
      decoder.userInfo[databaseInstanceIdKey] as? String
    } else {
      String?.none
    }
    let derivedId = decoder.codingPath.last?.stringValue

    guard let id = explicitId ?? derivedId else {
        throw DatabaseInstanceIdDecodingError.missingIdentifierString
    }
    guard let uuid = UUID(uuidString: id) else {
        throw DatabaseInstanceIdDecodingError.invalidUUID
    }

    self.id = uuid
    self.levels = try container.decodeIfPresent(Int.self, forKey: .levels)
    self.subtype = try container.decodeIfPresent(AdvantageDisadvantageSubtype.self, forKey: .subtype)
    self.nameBuilderRules = try container.decodeIfPresent(ActivatableNameBuilderRules.self, forKey: .nameBuilderRules)
    self.selectOptions = try container.decodeIfPresent(SelectOptions.self, forKey: .selectOptions)
    self.maximum = try container.decodeIfPresent(Int.self, forKey: .maximum)
    self.prerequisites = try container.decodeIfPresent(AdvantageDisadvantagePrerequisites.self, forKey: .prerequisites)
    self.apValue = try container.decode(AdventurePointsValue.self, forKey: .apValue)
    self.hasMaximumSpentInfluence = try container.decode(Bool.self, forKey: .hasMaximumSpentInfluence)
    self.isExclusiveToArcaneSpellworks = try container.decode(Bool.self, forKey: .isExclusiveToArcaneSpellworks)
    self.src = try container.decode(PublicationRefs.self, forKey: .src)
    self.translations = try container.decode(LocaleMap<DisadvantageTranslation>.self, forKey: .translations)
  }
}

public struct DisadvantageTranslation: Decodable, Equatable, Sendable {
  /// Name of the activatable entry.
  public let name: String

  /// The full name of the entry as stated in the sources. Only use when `name` needs to be different from full name for text generation purposes.
  public let nameInLibrary: String?

  /// A string that is used as a label for an input field.
  public let input: String?

  /// The rule text.
  public let rules: String

  /// The range.
  public let range: String?

  /// The string to append to the generated AP value text.
  @available(*, deprecated)
  public let apValueAppend: String?

  /// The adventure points value.
  @available(*, deprecated)
  public let apValue: String?

  public let errata: Errata?

  private enum CodingKeys: String, CodingKey {
    case name = "name"
    case nameInLibrary = "name_in_library"
    case input = "input"
    case rules = "rules"
    case range = "range"
    case apValueAppend = "ap_value_append"
    case apValue = "ap_value"
    case errata = "errata"
  }

  public init(from decoder: Decoder) throws {
    let container = try decoder.container(keyedBy: CodingKeys.self)

    self.name = try container.decode(String.self, forKey: .name)
    self.nameInLibrary = try container.decodeIfPresent(String.self, forKey: .nameInLibrary)
    self.input = try container.decodeIfPresent(String.self, forKey: .input)
    self.rules = try container.decode(String.self, forKey: .rules)
    self.range = try container.decodeIfPresent(String.self, forKey: .range)
    self.apValueAppend = try container.decodeIfPresent(String.self, forKey: .apValueAppend)
    self.apValue = try container.decodeIfPresent(String.self, forKey: .apValue)
    self.errata = try container.decodeIfPresent(Errata.self, forKey: .errata)
  }
}

/// Registers new skill applications, which get enabled once the referenced entry is activated. It specifies the skill(s) it belongs to. A translation can be left out if its name equals the name of the origin activatable entry.
public struct NewSkillApplication: Decodable, Equatable, Sendable, Identifiable, ChildEntity {
  public typealias ParentID = NewSkillApplicationOrUseParentIdentifier
  public static let parentId: KeyPath<Self, ParentID> & Sendable = \.parent

  public typealias ID = UUID

  public let id: ID

  /// The entry that enables the new skill application.
  public let parent: NewSkillApplicationOrUseParentIdentifier

  /// The skill(s) this application belongs to.
  public let skills: [Skill.ID]

  /// If an application applies to multiple skills, it may need to ensure the respective skill is on a certain skill rating if the activatable entry cannot ensure this prerequisite.
  public let requiredSkillRating: Int?

  /// All translations for the entry, identified by IETF language tag (BCP47).
  public let translations: LocaleMap<NewSkillApplicationTranslation>?

  private enum CodingKeys: String, CodingKey {
    case parent = "parent"
    case skills = "skills"
    case requiredSkillRating = "required_skill_rating"
    case translations = "translations"
  }

  public init(from decoder: Decoder) throws {
    let container = try decoder.container(keyedBy: CodingKeys.self)

    let databaseInstanceIdKey = CodingUserInfoKey.databaseInstanceIdKey
    let explicitId = if let databaseInstanceIdKey {
      decoder.userInfo[databaseInstanceIdKey] as? String
    } else {
      String?.none
    }
    let derivedId = decoder.codingPath.last?.stringValue

    guard let id = explicitId ?? derivedId else {
        throw DatabaseInstanceIdDecodingError.missingIdentifierString
    }
    guard let uuid = UUID(uuidString: id) else {
        throw DatabaseInstanceIdDecodingError.invalidUUID
    }

    self.id = uuid
    self.parent = try container.decode(NewSkillApplicationOrUseParentIdentifier.self, forKey: .parent)
    self.skills = try container.decode([Skill.ID].self, forKey: .skills)
    self.requiredSkillRating = try container.decodeIfPresent(Int.self, forKey: .requiredSkillRating)
    self.translations = try container.decodeIfPresent(LocaleMap<NewSkillApplicationTranslation>.self, forKey: .translations)
  }
}

public struct NewSkillApplicationTranslation: Decodable, Equatable, Sendable {
  /// The name of the application if different from the activatable entry’s name.
  public let name: String

  private enum CodingKeys: String, CodingKey {
    case name = "name"
  }

  public init(from decoder: Decoder) throws {
    let container = try decoder.container(keyedBy: CodingKeys.self)

    self.name = try container.decode(String.self, forKey: .name)
  }
}

public enum NewSkillApplicationOrUseParentIdentifier: Decodable, Equatable, Sendable {
  case generalSelectOption(GeneralSelectOption.ID)
  case advantage(Advantage.ID)
  case disadvantage(Disadvantage.ID)
  case advancedCombatSpecialAbility(AdvancedCombatSpecialAbility.ID)
  case advancedKarmaSpecialAbility(AdvancedKarmaSpecialAbility.ID)
  case advancedMagicalSpecialAbility(AdvancedMagicalSpecialAbility.ID)
  case advancedSkillSpecialAbility(AdvancedSkillSpecialAbility.ID)
  case blessedTradition(BlessedTradition.ID)
  case ceremonialItemSpecialAbility(CeremonialItemSpecialAbility.ID)
