  /// If the publication may contain adult content.
  public let containsAdultContent: Bool

  /// If the publication is not (fully) implemented and thus needs to be excluded from stable releases.
  public let isMissingImplementation: Bool

  public let prerequisites: PublicationPrerequisites?

  /// All translations for the entry, identified by IETF language tag (BCP47).
  public let translations: LocaleMap<PublicationTranslation>

  private enum CodingKeys: String, CodingKey {
    case category = "category"
    case containsAdultContent = "containsAdultContent"
    case isMissingImplementation = "isMissingImplementation"
    case prerequisites = "prerequisites"
    case translations = "translations"
  }

  public init(from decoder: Decoder) throws {
    let container = try decoder.container(keyedBy: CodingKeys.self)

    let databaseInstanceIdKey = CodingUserInfoKey.databaseInstanceIdKey
    let explicitId = if let databaseInstanceIdKey {
      decoder.userInfo[databaseInstanceIdKey] as? String
    } else {
      String?.none
    }
    let derivedId = decoder.codingPath.last?.stringValue

    guard let id = explicitId ?? derivedId else {
        throw DatabaseInstanceIdDecodingError.missingIdentifierString
    }
    guard let uuid = UUID(uuidString: id) else {
        throw DatabaseInstanceIdDecodingError.invalidUUID
    }

    self.id = uuid
    self.category = try container.decode(PublicationCategory.self, forKey: .category)
    self.containsAdultContent = try container.decode(Bool.self, forKey: .containsAdultContent)
    self.isMissingImplementation = try container.decode(Bool.self, forKey: .isMissingImplementation)
    self.prerequisites = try container.decodeIfPresent(PublicationPrerequisites.self, forKey: .prerequisites)
    self.translations = try container.decode(LocaleMap<PublicationTranslation>.self, forKey: .translations)
  }
}

