public enum MathOperation<Value: Decodable & Equatable & Sendable>: Decodable, Equatable, Sendable {
  /// A direct value.
  case value(Value)

  /// Adds two values.
  indirect case addition([2 of MathOperation<Value>])

  /// Subtracts the right value from the left value.
  indirect case subtraction([2 of MathOperation<Value>])

  /// Multiplies two values.
  indirect case multiplication([2 of MathOperation<Value>])

  /// Divides the left value by the right value.
  indirect case division([2 of MathOperation<Value>])

  /// Raises the left value to the power of the right value.
  indirect case exponentiation([2 of MathOperation<Value>])

  private enum CodingKeys: String, CodingKey {
    case tag = "kind"
    case value = "Value"
    case addition = "Addition"
    case subtraction = "Subtraction"
    case multiplication = "Multiplication"
    case division = "Division"
    case exponentiation = "Exponentiation"
  }

  private enum Discriminator: String, Decodable {
    case value = "Value"
    case addition = "Addition"
    case subtraction = "Subtraction"
    case multiplication = "Multiplication"
    case division = "Division"
    case exponentiation = "Exponentiation"
  }

  public init(from decoder: Decoder) throws {
    let container = try decoder.container(keyedBy: CodingKeys.self)
    let tag = try container.decode(Discriminator.self, forKey: .tag)
    switch tag {
    case .value:
      self = .value(try container.decode(Value.self, forKey: .value))
    case .addition:
      self = .addition(try container.decode([2 of MathOperation<Value>].self, forKey: .addition))
    case .subtraction:
      self = .subtraction(try container.decode([2 of MathOperation<Value>].self, forKey: .subtraction))
    case .multiplication:
      self = .multiplication(try container.decode([2 of MathOperation<Value>].self, forKey: .multiplication))
    case .division:
      self = .division(try container.decode([2 of MathOperation<Value>].self, forKey: .division))
    case .exponentiation:
      self = .exponentiation(try container.decode([2 of MathOperation<Value>].self, forKey: .exponentiation))
    }
  }
}

