/// An effect or other parameter that may be reduced by a failed disease check for lessening or a degraded poison.
///
/// This streamlines the wording for diseases and poison by using a unified wording for *lessened* (disease) and *degraded* (poison).
public struct Reduceable<Content: Decodable & Equatable & Sendable>: Decodable, Equatable, Sendable {
  /// The default value. In the source, it's the text before the slash.
  public let `default`: Content

  /// The reduced value. In the source, it's the text after the slash. Some entries may not have a reduced value, i.e. there is no slash with text after it. If the text after the slash is a dash, include it here as well.
  public let reduced: Content?

  /// An additional text that applies regardless of the effect being reduced or not.
  public let additonal: String?

  private enum CodingKeys: String, CodingKey {
    case `default` = "default"
    case reduced = "reduced"
    case additonal = "additonal"
  }

  public init(from decoder: Decoder) throws {
    let container = try decoder.container(keyedBy: CodingKeys.self)

    self.`default` = try container.decode(Content.self, forKey: .`default`)
    self.reduced = try container.decodeIfPresent(Content.self, forKey: .reduced)
    self.additonal = try container.decodeIfPresent(String.self, forKey: .additonal)
  }
}

public struct Poison: Decodable, Equatable, Sendable, Identifiable {
  public typealias ID = UUID

  public let id: ID

  /// The poison’s application type(s).
  public let applicationType: [PoisonApplicationType]

  /// The poison’s source type and dependent additional values.
  public let sourceType: PoisonSourceType

  /// Use Spirit or Toughness as a modifier for the poison.
  public let resistance: Resistance

  /// When the poison takes effect.
  public let start: PoisonStart

  /// The normal and degraded poison’s duration.
  public let duration: Reduceable<PoisonDuration>

  /// The raw (ingredients) value per level, in silverthalers.
  public let value: Int?

  /// Price for one dose, in silverthalers.
  public let cost: PoisonCost?

  /// The prerequisites of the item, if any. Note that this is fully separate from the prerequisites of the item’s trade secret, which are defined independently from this.
  public let prerequisites: EquipmentPrerequisites?

  /// References to where in which publications this entry has been defined. Entries may also be added or removed in later printings.
  public let src: PublicationRefs

  /// All translations for the entry, identified by IETF language tag (BCP47).
  public let translations: LocaleMap<PoisonTranslation>

  private enum CodingKeys: String, CodingKey {
    case applicationType = "application_type"
    case sourceType = "source_type"
    case resistance = "resistance"
    case start = "start"
    case duration = "duration"
    case value = "value"
    case cost = "cost"
    case prerequisites = "prerequisites"
    case src = "src"
    case translations = "translations"
  }

  public init(from decoder: Decoder) throws {
    let container = try decoder.container(keyedBy: CodingKeys.self)

    let databaseInstanceIdKey = CodingUserInfoKey.databaseInstanceIdKey
    let explicitId = if let databaseInstanceIdKey {
      decoder.userInfo[databaseInstanceIdKey] as? String
    } else {
      String?.none
    }
    let derivedId = decoder.codingPath.last?.stringValue

    guard let id = explicitId ?? derivedId else {
        throw DatabaseInstanceIdDecodingError.missingIdentifierString
    }
    guard let uuid = UUID(uuidString: id) else {
        throw DatabaseInstanceIdDecodingError.invalidUUID
    }

    self.id = uuid
    self.applicationType = try container.decode([PoisonApplicationType].self, forKey: .applicationType)
    self.sourceType = try container.decode(PoisonSourceType.self, forKey: .sourceType)
    self.resistance = try container.decode(Resistance.self, forKey: .resistance)
    self.start = try container.decode(PoisonStart.self, forKey: .start)
    self.duration = try container.decode(Reduceable<PoisonDuration>.self, forKey: .duration)
    self.value = try container.decodeIfPresent(Int.self, forKey: .value)
    self.cost = try container.decodeIfPresent(PoisonCost.self, forKey: .cost)
    self.prerequisites = try container.decodeIfPresent(EquipmentPrerequisites.self, forKey: .prerequisites)
    self.src = try container.decode(PublicationRefs.self, forKey: .src)
    self.translations = try container.decode(LocaleMap<PoisonTranslation>.self, forKey: .translations)
  }
}

