public struct Enhancement: Decodable, Equatable, Sendable, Identifiable, ChildEntity {
  public typealias ParentID = SkillWithEnhancementsIdentifier
  public static let parentId: KeyPath<Self, ParentID> & Sendable = \.parent

  public typealias ID = UUID

  public let id: ID

  /// The spellwork or liturgy this enhancement belongs to
  public let parent: SkillWithEnhancementsIdentifier

  /// The skill rating required to learn this enhancement.
  public let skillRating: Int

  /// Defines how to determine the AP cost of an enhancement.
  public let adventurePoints: EnhancementAdventurePoints

  public let prerequisites: EnhancementPrerequisites?

  /// Only defined if different than the associated skill.
  public let src: PublicationRefs?

  /// All translations for the entry, identified by IETF language tag (BCP47).
  public let translations: LocaleMap<EnhancementTranslation>

  private enum CodingKeys: String, CodingKey {
    case parent = "parent"
    case skillRating = "skill_rating"
    case adventurePoints = "adventurePoints"
    case prerequisites = "prerequisites"
    case src = "src"
    case translations = "translations"
  }

  public init(from decoder: Decoder) throws {
    let container = try decoder.container(keyedBy: CodingKeys.self)

    let databaseInstanceIdKey = CodingUserInfoKey.databaseInstanceIdKey
    let explicitId = if let databaseInstanceIdKey {
      decoder.userInfo[databaseInstanceIdKey] as? String
    } else {
      String?.none
    }
    let derivedId = decoder.codingPath.last?.stringValue

    guard let id = explicitId ?? derivedId else {
        throw DatabaseInstanceIdDecodingError.missingIdentifierString
    }
    guard let uuid = UUID(uuidString: id) else {
        throw DatabaseInstanceIdDecodingError.invalidUUID
    }

    self.id = uuid
    self.parent = try container.decode(SkillWithEnhancementsIdentifier.self, forKey: .parent)
    self.skillRating = try container.decode(Int.self, forKey: .skillRating)
    self.adventurePoints = try container.decode(EnhancementAdventurePoints.self, forKey: .adventurePoints)
    self.prerequisites = try container.decodeIfPresent(EnhancementPrerequisites.self, forKey: .prerequisites)
    self.src = try container.decodeIfPresent(PublicationRefs.self, forKey: .src)
    self.translations = try container.decode(LocaleMap<EnhancementTranslation>.self, forKey: .translations)
  }
}

