public struct Weapon: Decodable, Equatable, Sendable, Identifiable {
  public typealias ID = UUID

  public let id: ID

  /// The cost in silverthalers.
  public let cost: Cost?

  /// The weight in kg.
  public let weight: Weight?

  /// The complexity of crafting the item.
  public let complexity: Complexity?

  /// The structure points of the item. Use an array if the item consists of multiple components that have individual structure points.
  public let structurePoints: StructurePoints?

  /// A list of stat blocks for each close combat technique this weapon can be used with.
  public let meleeUses: [CloseCombatTechnique.ID: MeleeWeaponUse]?

  /// A list of stat blocks for each ranged combat technique this weapon can be used with.
  public let rangedUses: [RangedCombatTechnique.ID: RangedWeaponUse]?

  /// Define if during character creation this weapon can only be bought by a specific subset of characters.
  public let restrictedTo: RestrictedTo?

  /// The weapon is a known item, which implies some additional values.
  public let knownItemSpecifics: KnownItemSpecifics?

  /// The prerequisites of the item, if any. Note that this is fully separate from the prerequisites of the item’s trade secret, which are defined independently from this.
  public let prerequisites: EquipmentPrerequisites?

  /// References to where in which publications this entry has been defined. Entries may also be added or removed in later printings.
  public let src: PublicationRefs

  /// All translations for the entry, identified by IETF language tag (BCP47).
  public let translations: LocaleMap<WeaponTranslation>

  private enum CodingKeys: String, CodingKey {
    case cost = "cost"
    case weight = "weight"
    case complexity = "complexity"
    case structurePoints = "structure_points"
    case meleeUses = "melee_uses"
    case rangedUses = "ranged_uses"
    case restrictedTo = "restrictedTo"
    case knownItemSpecifics = "knownItemSpecifics"
    case prerequisites = "prerequisites"
    case src = "src"
    case translations = "translations"
  }

  public init(from decoder: Decoder) throws {
    let container = try decoder.container(keyedBy: CodingKeys.self)

    let databaseInstanceIdKey = CodingUserInfoKey.databaseInstanceIdKey
    let explicitId = if let databaseInstanceIdKey {
      decoder.userInfo[databaseInstanceIdKey] as? String
    } else {
      String?.none
    }
    let derivedId = decoder.codingPath.last?.stringValue

    guard let id = explicitId ?? derivedId else {
        throw DatabaseInstanceIdDecodingError.missingIdentifierString
    }
    guard let uuid = UUID(uuidString: id) else {
        throw DatabaseInstanceIdDecodingError.invalidUUID
    }

    self.id = uuid
    self.cost = try container.decodeIfPresent(Cost.self, forKey: .cost)
    self.weight = try container.decodeIfPresent(Weight.self, forKey: .weight)
    self.complexity = try container.decodeIfPresent(Complexity.self, forKey: .complexity)
    self.structurePoints = try container.decodeIfPresent(StructurePoints.self, forKey: .structurePoints)
    self.meleeUses = try container.decodeIfPresent([CloseCombatTechnique.ID: MeleeWeaponUse].self, forKey: .meleeUses)
    self.rangedUses = try container.decodeIfPresent([RangedCombatTechnique.ID: RangedWeaponUse].self, forKey: .rangedUses)
    self.restrictedTo = try container.decodeIfPresent(RestrictedTo.self, forKey: .restrictedTo)
    self.knownItemSpecifics = try container.decodeIfPresent(KnownItemSpecifics.self, forKey: .knownItemSpecifics)
    self.prerequisites = try container.decodeIfPresent(EquipmentPrerequisites.self, forKey: .prerequisites)
    self.src = try container.decode(PublicationRefs.self, forKey: .src)
    self.translations = try container.decode(LocaleMap<WeaponTranslation>.self, forKey: .translations)
  }
}

public typealias MeleeWeaponUse = MeleeWeapon

public typealias RangedWeaponUse = RangedWeapon

