public struct RaceVariant: Decodable, Equatable, Sendable, Identifiable, ChildEntity {
  public typealias ParentID = Race.ID
  public static let parentId: KeyPath<Self, ParentID> & Sendable = \.race

  public typealias ID = UUID

  public let id: ID

  /// The associated race.
  public let race: Race.ID

  /// Describes how to raise or lower maximum attribute values during character creation.
  public let attributeAdjustments: AttributeAdjustments

  /// The list of common cultures.
  public let commonCultures: [Culture.ID]?

  /// A list of automatically applied advantages.
  public let automaticAdvantages: [AutomaticAdvantageDisadvantage<Advantage.ID>]?

  /// A list of automatically applied disadvantages.
  public let automaticDisadvantages: [AutomaticAdvantageDisadvantage<Disadvantage.ID>]?

  /// A list of strongly recommended advantages.
  public let stronglyRecommendedAdvantages: [AutomaticAdvantageDisadvantage<Advantage.ID>]?

  /// A list of strongly recommended disadvantages.
  public let stronglyRecommendedDisadvantages: [AutomaticAdvantageDisadvantage<Disadvantage.ID>]?

  /// A list of common advantages.
  public let commonAdvantages: [CommonnessRatedAdvantageDisadvantage<Advantage.ID>]?

  /// A list of common disadvantages.
  public let commonDisadvantages: [CommonnessRatedAdvantageDisadvantage<Disadvantage.ID>]?

  /// A list of uncommon advantages.
  public let uncommonAdvantages: [CommonnessRatedAdvantageDisadvantage<Advantage.ID>]?

  /// A list of uncommon disadvantages.
  public let uncommonDisadvantages: [CommonnessRatedAdvantageDisadvantage<Disadvantage.ID>]?

  /// An array containing 20 (numeric) hair color identifiers. The array also represents the 20-sided die for a random hair color.
  public let hairColor: [20 of HairColor.ID]

  /// An array containing 20 (numeric) eye color identifiers. The array also represents the 20-sided die for a random eye color.
  public let eyeColor: [20 of EyeColor.ID]

  /// Configuration for random height generation.
  public let height: RandomHeightGeneration

  /// All translations for the entry, identified by IETF language tag (BCP47).
  public let translations: LocaleMap<RaceVariantTranslation>

  private enum CodingKeys: String, CodingKey {
    case race = "race"
    case attributeAdjustments = "attribute_adjustments"
    case commonCultures = "common_cultures"
    case automaticAdvantages = "automatic_advantages"
    case automaticDisadvantages = "automatic_disadvantages"
    case stronglyRecommendedAdvantages = "strongly_recommended_advantages"
    case stronglyRecommendedDisadvantages = "strongly_recommended_disadvantages"
    case commonAdvantages = "common_advantages"
    case commonDisadvantages = "common_disadvantages"
    case uncommonAdvantages = "uncommon_advantages"
    case uncommonDisadvantages = "uncommon_disadvantages"
    case hairColor = "hair_color"
    case eyeColor = "eye_color"
    case height = "height"
    case translations = "translations"
  }

  public init(from decoder: Decoder) throws {
    let container = try decoder.container(keyedBy: CodingKeys.self)

    let databaseInstanceIdKey = CodingUserInfoKey.databaseInstanceIdKey
    let explicitId = if let databaseInstanceIdKey {
      decoder.userInfo[databaseInstanceIdKey] as? String
    } else {
      String?.none
    }
    let derivedId = decoder.codingPath.last?.stringValue

    guard let id = explicitId ?? derivedId else {
        throw DatabaseInstanceIdDecodingError.missingIdentifierString
    }
    guard let uuid = UUID(uuidString: id) else {
        throw DatabaseInstanceIdDecodingError.invalidUUID
    }

    self.id = uuid
    self.race = try container.decode(Race.ID.self, forKey: .race)
    self.attributeAdjustments = try container.decode(AttributeAdjustments.self, forKey: .attributeAdjustments)
    self.commonCultures = try container.decodeIfPresent([Culture.ID].self, forKey: .commonCultures)
    self.automaticAdvantages = try container.decodeIfPresent([AutomaticAdvantageDisadvantage<Advantage.ID>].self, forKey: .automaticAdvantages)
    self.automaticDisadvantages = try container.decodeIfPresent([AutomaticAdvantageDisadvantage<Disadvantage.ID>].self, forKey: .automaticDisadvantages)
    self.stronglyRecommendedAdvantages = try container.decodeIfPresent([AutomaticAdvantageDisadvantage<Advantage.ID>].self, forKey: .stronglyRecommendedAdvantages)
    self.stronglyRecommendedDisadvantages = try container.decodeIfPresent([AutomaticAdvantageDisadvantage<Disadvantage.ID>].self, forKey: .stronglyRecommendedDisadvantages)
    self.commonAdvantages = try container.decodeIfPresent([CommonnessRatedAdvantageDisadvantage<Advantage.ID>].self, forKey: .commonAdvantages)
    self.commonDisadvantages = try container.decodeIfPresent([CommonnessRatedAdvantageDisadvantage<Disadvantage.ID>].self, forKey: .commonDisadvantages)
    self.uncommonAdvantages = try container.decodeIfPresent([CommonnessRatedAdvantageDisadvantage<Advantage.ID>].self, forKey: .uncommonAdvantages)
    self.uncommonDisadvantages = try container.decodeIfPresent([CommonnessRatedAdvantageDisadvantage<Disadvantage.ID>].self, forKey: .uncommonDisadvantages)
    self.hairColor = try container.decode([20 of HairColor.ID].self, forKey: .hairColor)
    self.eyeColor = try container.decode([20 of EyeColor.ID].self, forKey: .eyeColor)
    self.height = try container.decode(RandomHeightGeneration.self, forKey: .height)
    self.translations = try container.decode(LocaleMap<RaceVariantTranslation>.self, forKey: .translations)
  }
}

