  public typealias ID = UUID

  public let id: ID

  /// The tradition(s) the talisman belongs to.
  public let tradition: [BlessedTradition.ID]?

  /// The talisman type, if any.
  public let type: TalismanType?

  /// The activation parameters.
  public let activation: [TalismanActivation]?

  /// The AP value for the required trade secret, if possible.
  public let apValue: Int?

  public let combatUse: TalismanCombatUse?

  /// References to where in which publications this entry has been defined. Entries may also be added or removed in later printings.
  public let src: PublicationRefs

  /// All translations for the entry, identified by IETF language tag (BCP47).
  public let translations: LocaleMap<TalismanTranslation>

  private enum CodingKeys: String, CodingKey {
    case tradition = "tradition"
    case type = "type"
    case activation = "activation"
    case apValue = "ap_value"
    case combatUse = "combatUse"
    case src = "src"
    case translations = "translations"
  }

  public init(from decoder: Decoder) throws {
    let container = try decoder.container(keyedBy: CodingKeys.self)

    let databaseInstanceIdKey = CodingUserInfoKey.databaseInstanceIdKey
    let explicitId = if let databaseInstanceIdKey {
      decoder.userInfo[databaseInstanceIdKey] as? String
    } else {
      String?.none
    }
    let derivedId = decoder.codingPath.last?.stringValue

    guard let id = explicitId ?? derivedId else {
        throw DatabaseInstanceIdDecodingError.missingIdentifierString
    }
    guard let uuid = UUID(uuidString: id) else {
        throw DatabaseInstanceIdDecodingError.invalidUUID
    }

    self.id = uuid
    self.tradition = try container.decodeIfPresent([BlessedTradition.ID].self, forKey: .tradition)
    self.type = try container.decodeIfPresent(TalismanType.self, forKey: .type)
    self.activation = try container.decodeIfPresent([TalismanActivation].self, forKey: .activation)
    self.apValue = try container.decodeIfPresent(Int.self, forKey: .apValue)
    self.combatUse = try container.decodeIfPresent(TalismanCombatUse.self, forKey: .combatUse)
    self.src = try container.decode(PublicationRefs.self, forKey: .src)
    self.translations = try container.decode(LocaleMap<TalismanTranslation>.self, forKey: .translations)
  }
}

